[FunctionName("DocumentProcessingOrchestrator")]
public async Task Run(
    [OrchestrationTrigger] TaskOrchestrationContext context)
{
    var documentId = context.GetInput<string>();

    // Step 1: Ingest document (checkpoint here)
    var chunks = await context.CallActivityAsync<string[]>(
        "ChunkDocument", 
        documentId);

    // Step 2: Generate embeddings (parallel)
    var embeddingTasks = chunks.Select(chunk => 
        context.CallActivityAsync<float[]>("GenerateEmbedding", chunk));
    var embeddings = await Task.WhenAll(embeddingTasks);

    // Step 3: Store in vector database
    await context.CallActivityAsync(
        "StoreInVectorDb", 
        (documentId, chunks, embeddings));

    // Step 4: Update index
    await context.CallActivityAsync(
        "UpdateSearchIndex", 
        documentId);

    return "Processing complete";
}

// Idempotent activity
[FunctionName("StoreInVectorDb")]
public async Task StoreInVectorDb(
    [ActivityTrigger] (string documentId, string[] chunks, float[][] embeddings) input,
    ILogger log)
{
    var (docId, chunks, embeddings) = input;

    // Use upsert for idempotency
    var upserted = await _vectorStore.UpsertAsync(
        documentId: docId,
        chunks: chunks,
        embeddings: embeddings,
        options: new UpsertOptions { IfMatchETag = null } // overwrite if exists
    );

    log.LogInformation("Upserted {Count} vectors for document {DocumentId}", upserted, docId);
}

// Idempotency pattern for HTTP endpoints
public class IdempotentRequestHandler
{
    private readonly IIdempotencyStore _store;

    public async Task<T> HandleAsync<T>(
        string idempotencyKey,
        Func<Task<T>> operation,
        CancellationToken ct)
    {
        // Check if already processed
        var cached = await _store.GetAsync<T>(idempotencyKey, ct);
        if (cached != null)
        {
            return cached; // Return cached result
        }

        // Execute operation
        var result = await operation();

        // Store result with TTL
        await _store.SetAsync(idempotencyKey, result, TimeSpan.FromHours(24), ct);

        return result;
    }
}
